import { test, expect } from '@playwright/test';

test.describe('Access Denied Page Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/protected-resource');
  });

  test('should display access denied page on 403 error', async ({ page }) => {
    await page.route('**/protected-resource', (route) => {
      route.fulfill({
        status: 403,
        contentType: 'text/html',
        body: '<h1>Access Denied</h1><p>You do not have permission to view this resource.</p>',
      });
    });

    await page.reload();

    const accessDeniedHeading = await page.getByRole('heading', { name: /Access Denied/i });
    const accessDeniedMessage = await page.getByText(/You do not have permission to view this resource./i);

    await expect(accessDeniedHeading).toBeVisible();
    await expect(accessDeniedMessage).toBeVisible();
  });

  test('should not show access denied page on successful response', async ({ page }) => {
    await page.route('**/protected-resource', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'text/html',
        body: '<h1>Protected Resource</h1><p>Welcome to the protected resource.</p>',
      });
    });

    await page.reload();

    const protectedResourceHeading = await page.getByRole('heading', { name: /Protected Resource/i });
    const protectedResourceMessage = await page.getByText(/Welcome to the protected resource./i);

    await expect(protectedResourceHeading).toBeVisible();
    await expect(protectedResourceMessage).toBeVisible();
  });
});
